//! A diffuse floor receives a small area light through a smooth Principled Thin Wall pane. The
//! camera sees only the floor; after its diffuse bounce, shadow and BSDF rays encounter the pane.
//! The reference is the committed Blender 5.2.2 Cycles CPU capture generated by
//! `fixtures/native_oracle/principled/smooth_thin_wall_indirect.py`. The former BSDF+NEE overcount
//! was about 2x, so the measured-noise bound is also checked to remain narrower than the signal.

#[path = "common/blender_checked.rs"]
mod blender_checked;
#[path = "common/native_oracle.rs"]
#[expect(
    dead_code,
    reason = "the shared oracle helpers include support for unrelated tests"
)]
mod native_oracle;
#[path = "common/process.rs"]
mod process;

use std::path::{Path, PathBuf};

use blender_checked::blender_executable;
use native_oracle::{TestResult, apply_operations, checked, import_blend, pot, read_scene};
use potter_core::image::{ImageData, ImageInterpolation, load_image_data, sample};
use potter_core::model::Image;
use serde_json::{Value, json};
use tempfile::tempdir;

const CAPTURE: &str =
    include_str!("fixtures/native_oracle/principled/smooth_thin_wall_indirect.json");
const POTTER_SEEDS: [u64; 8] = [0, 1, 2, 3, 4, 5, 6, 7];
const SAMPLES: u64 = 4096;

fn render_patch_mean(project: &Path, root: &Path, seed: u64) -> TestResult<[f64; 3]> {
    let id = format!("smooth_thin_wall_indirect_seed{seed}");
    let frames = root.join(format!("{id}_frames"));
    let mut render = pot();
    render
        .arg("render")
        .arg(project)
        .args(["--format", "exr", "--out"])
        .arg(&frames)
        .arg("--json");
    let output = checked(&mut render, "smooth Thin Wall indirect render")?;
    let response: Value = serde_json::from_slice(&output.stdout)?;
    assert_eq!(response["result"]["warnings"], json!([]), "{response}");

    let exr = frames.join("frame_0001.exr");
    let loaded = apply_operations(
        project,
        root,
        json!([{"op":"image.load","id":id,"path":exr.to_string_lossy()}]),
    )?;
    assert_eq!(loaded["ok"], true, "{loaded}");
    let scene = read_scene(project)?;
    let image: Image = serde_json::from_value(scene["images"][&id].clone())?;
    let data = load_image_data(&image, project, ImageInterpolation::Closest)?;
    Ok(patch_mean(&data))
}

fn patch_mean(data: &ImageData) -> [f64; 3] {
    let mut total = [0.0; 3];
    for y in 4..12 {
        for x in 4..12 {
            let pixel = sample(
                data,
                [((x as f64) + 0.5) / 16.0, ((y as f64) + 0.5) / 16.0],
                false,
            );
            for (sum, value) in total.iter_mut().zip(pixel.iter().take(3)) {
                *sum += value;
            }
        }
    }
    total.map(|value| value / 64.0)
}

fn capture_vector(value: &Value) -> TestResult<[f64; 3]> {
    let values = value.as_array().ok_or("capture vector is missing")?;
    let mut result = [0.0; 3];
    for (destination, source) in result.iter_mut().zip(values) {
        *destination = source.as_f64().ok_or("capture value is not a number")?;
    }
    Ok(result)
}

fn standard_error(samples: &[[f64; 3]], channel: usize) -> f64 {
    let mean = samples.iter().map(|sample| sample[channel]).sum::<f64>() / samples.len() as f64;
    let variance = samples
        .iter()
        .map(|sample| (sample[channel] - mean).powi(2))
        .sum::<f64>()
        / (samples.len() - 1) as f64;
    variance.sqrt() / (samples.len() as f64).sqrt()
}

fn fixture() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("tests/fixtures/native_oracle/principled/smooth_thin_wall_indirect.blend")
}

#[test]
fn principled_smooth_thin_wall_indirect_matches_cycles() -> TestResult {
    let Some(blender) = blender_executable() else {
        return Ok(());
    };
    let expected: Value = serde_json::from_str(CAPTURE)?;
    let mean = capture_vector(&expected["mean"])?;
    let blender_stderr = capture_vector(&expected["stderr"])?;
    let root = tempdir()?;
    let (project, imported) = import_blend(
        &blender,
        root.path(),
        "smooth_thin_wall_indirect",
        &fixture(),
    )?;
    assert_eq!(imported["ok"], true, "{imported}");
    let scene = read_scene(&project)?;
    let active = scene["active_scene"]
        .as_str()
        .ok_or("active scene is missing")?;
    let updated = apply_operations(
        &project,
        root.path(),
        json!([{
            "op":"render.update",
            "target":{"id":active},
            "set":{"resolution_x":16,"resolution_y":16,"resolution_percentage":100,"samples":SAMPLES,"seed":0,"max_bounces":8}
        }]),
    )?;
    assert_eq!(updated["ok"], true, "{updated}");

    let mut samples = Vec::with_capacity(POTTER_SEEDS.len());
    for seed in POTTER_SEEDS {
        let updated = apply_operations(
            &project,
            root.path(),
            json!([{
                "op":"render.update",
                "target":{"id":active},
                "set":{"seed":seed}
            }]),
        )?;
        assert_eq!(updated["ok"], true, "{updated}");
        samples.push(render_patch_mean(&project, root.path(), seed)?);
    }
    let actual: [f64; 3] = std::array::from_fn(|channel| {
        samples.iter().map(|sample| sample[channel]).sum::<f64>() / samples.len() as f64
    });
    eprintln!("smooth Thin Wall indirect Potter CLI: {actual:?}");
    for channel in 0..3 {
        let tolerance = 4.0 * blender_stderr[channel].hypot(standard_error(&samples, channel));
        assert!(
            mean[channel] > tolerance,
            "channel {channel}: the Cycles signal {} must exceed its measured-noise tolerance {tolerance}, so a 2x result remains detectable",
            mean[channel]
        );
        assert!(
            (actual[channel] - mean[channel]).abs() <= tolerance,
            "channel {channel}: Potter {} vs Blender Cycles {} (tolerance {tolerance}); the former BSDF+NEE result was about 2x",
            actual[channel],
            mean[channel]
        );
    }
    Ok(())
}
